  const minorOffsets: Record<string, number> = { i: 0, "ii°": 2, III: 3, iv: 5, v: 7, V: 7, VI: 8, VII: 10 };
  let offset = (mode === "minor" ? minorOffsets : majorOffsets)[role];
  let suffix = ["ii", "iii", "vi", "i", "iv", "v"].includes(role) ? "m" : role.includes("°") ? "dim" : "";
