    {fallback ? <p className="chart-fallback" role="note">Fallback: {fallback}</p> : null}{!pitchCheck.matches ? <p className="chart-tuning-warning" role="alert"><strong>Pitch warning:</strong> {pitchCheck.message}</p> : pitchCheck.partial ? <p className="chart-tuning-note" role="note">Partial voicing: {pitchCheck.message}</p> : null}
    {instrument === "guitar" ? <ChordDiagram chord={entry.chord} orientation={orientation} highContrast={highContrast} scaleContacts={scaleContacts} /> : <div className="chart-instrument-warning" role="note"><strong>{INSTRUMENT_LABELS[instrument]}</strong><p>{INSTRUMENT_GUIDANCE[instrument]}</p><p><strong>Required pitch set:</strong> {chordTones(entry)}. The guitar shape and guitar-string note strip are hidden so they cannot be mistaken for this instrument&apos;s voicing.</p></div>}
    {instrument === "guitar" ? <div className="chart-string-overlay" aria-label={`String notes ${notes.join(" ")}`}><strong>String notes</strong>{notes.map((note, index) => <span key={STRINGS[index]} className={note === "×" ? "muted" : ""}>{note}<small>{note === "×" ? "avoid" : STRINGS[index]}</small></span>)}</div> : null}
