    {viewMode === "print" ? <section className="chart-view-panel chart-view-panel-print" aria-label="Print controls"><span className="label">Print</span><h2>Selected chord chart</h2><p className="muted">Print uses the expanded arrangement bars, cues, endings, and logical page breaks. Only selected cards print by default.</p><div className="chart-settings-grid"><label>Paper<select value={paperSize} onChange={(event) => setPaperSize(event.target.value as PaperSize)}><option value="letter">US Letter</option><option value="a4">A4</option></select></label><label>Margins<select value={printMargin} onChange={(event) => setPrintMargin(event.target.value as PrintMargin)}><option value="narrow">Narrow</option><option value="normal">Normal</option><option value="wide">Wide</option></select></label><label>Columns<select value={columns} onChange={(event) => setColumns(Number(event.target.value) as PrintColumns)}><option value={2}>2 columns</option><option value={3}>3 columns</option></select></label><label>Card layout<select value={layout} onChange={(event) => setLayout(event.target.value as Layout)}><option value="full">Full cards</option><option value="compact">Compact cards</option></select></label></div><p>{selectedEntries.length} selected card{selectedEntries.length === 1 ? "" : "s"} · approximately {printPageEstimate} page{printPageEstimate === 1 ? "" : "s"} · {expandedArrangement.length} timed occurrences · {activeArrangement.sections.length} sections</p><div className="chart-action-row"><button className="btn primary" type="button" onClick={() => printChart()} disabled={!selectedEntries.length}>Print selected</button><span className="muted">{selectedEntries.length ? "The selected order is preserved." : "Select cards in Browse or Build before printing; the full library will not print accidentally."}</span></div></section> : null}
